fn solve(x: i8) -> u8 {
    // Normalize x into [0, 360)
    let x_norm = {
        let v = x as i32 % 360;
        if v < 0 { v + 360 } else { v }
    };

    // We'll search for the best rotation r in 0..=3
    // that minimizes the deviation from vertical.
    let mut best_r: u8 = 0;
    let mut best_d: i32 = 181; // max possible deviation is 180

    for r in 0..4 {
        // Compute the resulting orientation A = (-x_norm + 90*r) mod 360
        let raw = -x_norm + r * 90;
        let a = {
            let v = raw % 360;
            if v < 0 { v + 360 } else { v }
        };

        // Deviation from vertical is min(A, 360 - A)
        let d = if a <= 180 { a } else { 360 - a };

        // Update best if we find a smaller deviation,
        // or the same deviation with a smaller r.
        if d < best_d || (d == best_d && (r as u8) < best_r) {
            best_d = d;
            best_r = r as u8;
        }
    }

    best_r
}

